// The raster + font probe (2026-10-22, the owner's "a way to use not only vector files"): the scene it draws
// (mods/_artprobe/art/raster.scene.json, generated by rasterProbeScene), the images it uses (small ones committed under
// mods/_artprobe/art/, the two big ones generated at run time into the git-ignored art/generated/) and the measures
// editor/scripts/art-probe.ts --raster applies to the harness shots. Pure (no node, no DOM).
//
// Clips, all with the probe marker (the yellow-bordered checker, probe-compare.ts analyzeProbeShot) for position,
// scale and mirroring:
//  - ArtProbeRaster (an enemy): a 32×32 four-colour PNG as a raster sprite ×2; a red/blue 4×1 stripe magnified ×32
//    smoothed (0x41) and pixel-snapped (0x43); a 2×2 tile repeated (0x40) over 4×2 periods; a 1024×768 "photo"
//    (three flat blocks and a 1-texel black/white checker block) minified ×0.25 — the mip question; a text in the
//    mod's own DefineFont3 "ProbeBlocks" (H = a solid square, I = a bar) and one with a glyph the font lacks;
//  - ArtProbeFontMissing: a text whose font class nobody exports (the probe build patches the class name);
//  - the cat frame probeRasterF/B (appended to CatTest like experiment A0) on a _CAT unit with palette 54: a 16-level
//    gray ramp as a bitmap and as vector gray:N squares — is a bitmap's gray palette-remapped like vector gray?
//  - ArtProbeBackdrop: a 2000×1500 two-colour plate scaled 0.7667 from (0,0), vanilla's combat_background recipe,
//    shown by _bgprobe's data/tilesets.gon.merge `alley { combat_background ArtProbeBackdrop }`.
//
// Every colour measure is tint-robust (the game multiplies units by a uniform tint of about 0.55..1.15, OBSERVED in the
// loc probe): colours are compared by chromaticity (channel ratios), not absolute values.

import type { Scene, SceneShape, SceneSprite, SceneKey } from "./scene.ts";
import type { RgbaImage } from "./png.ts";
import type { SceneFont } from "./font.ts";
import { FONT_EM } from "./font.ts";
import type { RgbaImageLike } from "./probe-compare.ts";
import type { ShotGeometry } from "./probe-outcomes.ts";

export type Rgb = [number, number, number];

// ---- layout (clip px relative to the marker's top-left; the marker is 96×64) -----------------------------------------
export const RASTER_PROBE = {
  quad: { x: 120, y: 0, size: 64 },
  quadColours: { tl: [32, 64, 255] as Rgb, tr: [32, 192, 64] as Rgb, bl: [255, 128, 0] as Rgb, br: [128, 0, 255] as Rgb },
  stripeSmooth: { x: 0, y: 90, w: 128, h: 16 },
  stripeSnapped: { x: 0, y: 120, w: 128, h: 16 },
  tile: { x: 0, y: 150, w: 64, h: 32, period: 16 },
  big: { x: 450, y: -230, w: 256, h: 192, texW: 1024, texH: 768 },
  bigColours: { tl: [208, 48, 48] as Rgb, tr: [48, 144, 208] as Rgb, bl: [48, 176, 96] as Rgb },
  text: { id: "fontText", x: 300, y: 120, w: 260, h: 50, size: 40, text: "HHIH", color: "#ff6000" },
  textMissing: { id: "fontTextMissing", x: 300, y: 190, w: 260, h: 50, size: 40, text: "HXH", color: "#ff6000" },
  /** the cat frame: rig-local positions, the marker at (-48, -330) like experiment A0's CatProbe */
  cat: { marker: { x: -48, y: -330 }, bitmapRamp: { x: -128, y: -380, w: 256, h: 24 }, vectorRamp: { x: -128, y: -410, w: 256, h: 24 }, palette: 54 },
  backdrop: { texW: 2000, texH: 1500, scale: 0.7667, left: [90, 45, 130] as Rgb, right: [45, 130, 90] as Rgb },
  /** the class name the font-missing clip's text names (the build patches "Peralta" to it: same length) */
  missingFontClass: "Pzzzzzz",
} as const;

// ---- images -------------------------------------------------------------------------------------------------------
function image(w: number, h: number, f: (x: number, y: number) => Rgb): RgbaImage {
  const rgba = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { const c = f(x, y); const i = (y * w + x) * 4; rgba[i] = c[0]; rgba[i + 1] = c[1]; rgba[i + 2] = c[2]; rgba[i + 3] = 255; }
  return { width: w, height: h, rgba };
}
const RED: Rgb = [255, 0, 0], BLUE: Rgb = [0, 0, 255];

/** The committed small PNGs (art/<name>.png) and the generated big ones (art/generated/<name>.png). */
export function rasterProbeImages(): { small: Record<string, RgbaImage>; generated: Record<string, RgbaImage> } {
  const q = RASTER_PROBE.quadColours, b = RASTER_PROBE.bigColours;
  return {
    small: {
      quad: image(32, 32, (x, y) => (y < 16 ? (x < 16 ? q.tl : q.tr) : x < 16 ? q.bl : q.br)),
      stripe: image(4, 1, (x) => (x % 2 ? BLUE : RED)),
      tile: image(2, 2, (x, y) => ((x + y) % 2 ? BLUE : RED)),
      gray16: image(16, 1, (x) => [x * 17, x * 17, x * 17]),
    },
    generated: {
      rasterbig: image(RASTER_PROBE.big.texW, RASTER_PROBE.big.texH, (x, y) => {
        const right = x >= 512, bottom = y >= 384;
        if (right && bottom) return (x + y) % 2 ? [255, 255, 255] : [0, 0, 0];
        return bottom ? b.bl : right ? b.tr : b.tl;
      }),
      backdrop: image(RASTER_PROBE.backdrop.texW, RASTER_PROBE.backdrop.texH, (x) => (x < 1000 ? RASTER_PROBE.backdrop.left : RASTER_PROBE.backdrop.right)),
    },
  };
}

/** "ProbeBlocks": H a solid 700-unit square, I a 100-unit bar, a space; nothing else (X is missing on purpose). */
export function probeBlocksFont(): SceneFont {
  return {
    name: "Probe Blocks",
    ascent: 800,
    descent: 224,
    glyphs: {
      H: { d: "M0 -700 L700 -700 L700 0 L0 0 Z", advance: 800 },
      I: { d: "M300 -700 L400 -700 L400 0 L300 0 Z", advance: 700 },
      " ": { d: "", advance: 400 },
    },
  };
}

const rect = (w: number, h: number) => `M0 0 L${w} 0 L${w} ${h} L0 ${h} Z`;
const place = (ref: string, x = 0, y = 0, extra: Partial<SceneKey> = {}): SceneKey => ({ frame: 0, ref, x, y, ...extra });

/** The raster probe scene (mods/_artprobe/art/raster.scene.json → swfs/raster.swf); the cat frame lives in probe.scene.json (withRasterCatFrame). */
export function rasterProbeScene(): Scene {
  const P = RASTER_PROBE;
  const shapes: Record<string, SceneShape> = {
    checker: { paths: [{ d: "M0 0 L12 0 L12 8 L0 8 Z", fill: "bitmap:checkerbmp", transform: [8, 0, 0, 8, 0, 0] }] },
    sq: { paths: [{ d: "M-30 -30 L30 -30 L30 30 L-30 30 Z", fill: "gray:8" }] },
    quad: { paths: [{ d: rect(32, 32), fill: "bitmap:quadbmp", transform: [P.quad.size / 32, 0, 0, P.quad.size / 32, 0, 0] }] },
    stripeSmooth: { paths: [{ d: rect(4, 1), fill: "bitmap:stripebmp", transform: [P.stripeSmooth.w / 4, 0, 0, P.stripeSmooth.h, 0, 0] }] },
    stripeSnapped: { paths: [{ d: rect(4, 1), fill: "bitmap:stripesnapbmp", transform: [P.stripeSnapped.w / 4, 0, 0, P.stripeSnapped.h, 0, 0] }] },
    tile: { paths: [{ d: rect(P.tile.w / (P.tile.period / 2), P.tile.h / (P.tile.period / 2)), fill: "bitmap:tilebmp", transform: [P.tile.period / 2, 0, 0, P.tile.period / 2, 0, 0] }] },
    big: { paths: [{ d: rect(P.big.texW, P.big.texH), fill: "bitmap:bigbmp", transform: [P.big.w / P.big.texW, 0, 0, P.big.w / P.big.texW, 0, 0] }] },
    backdrop: { paths: [{ d: rect(P.backdrop.texW, P.backdrop.texH), fill: "bitmap:backdropbmp", transform: [P.backdrop.scale, 0, 0, P.backdrop.scale, 0, 0] }] },
  };
  const t = (o: typeof P.text | typeof P.textMissing, font: string) => ({ text: o.text, font, size: o.size, color: o.color, align: "left" as const, width: o.w, height: o.h, html: false });
  const sprites: Record<string, SceneSprite> = {
    ArtProbeRaster: {
      frames: 1,
      layers: [
        { name: "marker", depth: 1, keys: [place("checker")] },
        { name: "cx", depth: 2, keys: [place("sq", 310, 30, { cxform: { mul: [1, 0, 0, 1] } })] },
        { name: "quad", depth: 3, keys: [place("quad", P.quad.x, P.quad.y)] },
        { name: "stripeSmooth", depth: 4, keys: [place("stripeSmooth", P.stripeSmooth.x, P.stripeSmooth.y)] },
        { name: "stripeSnapped", depth: 5, keys: [place("stripeSnapped", P.stripeSnapped.x, P.stripeSnapped.y)] },
        { name: "tile", depth: 6, keys: [place("tile", P.tile.x, P.tile.y)] },
        { name: "big", depth: 7, keys: [place("big", P.big.x, P.big.y)] },
        { name: "fontText", depth: 8, keys: [place(P.text.id, P.text.x, P.text.y)] },
        { name: "fontTextMissing", depth: 9, keys: [place(P.textMissing.id, P.textMissing.x, P.textMissing.y)] },
      ],
    },
    ArtProbeFontMissing: {
      frames: 1,
      layers: [
        { name: "marker", depth: 1, keys: [place("checker")] },
        { name: "cx", depth: 2, keys: [place("sq", 310, 30, { cxform: { mul: [1, 0, 0, 1] } })] },
        { name: "text", depth: 3, keys: [place("fontMissingText", P.text.x, P.text.y)] },
      ],
    },
    ArtProbeBackdrop: { frames: 1, layers: [{ name: "plate", depth: 1, keys: [place("backdrop")] }] },
  };
  return {
    version: 1,
    name: "raster",
    frameRate: 60,
    stage: { width: 1280, height: 720, background: "#000000" },
    preview: { palette: P.cat.palette },
    shapes,
    bitmaps: {
      checkerbmp: { file: "art/checker.png" },
      quadbmp: { file: "art/raster-quad.png" },
      stripebmp: { file: "art/raster-stripe.png" },
      stripesnapbmp: { file: "art/raster-stripe.png", smooth: false },
      tilebmp: { file: "art/raster-tile.png", repeat: true },
      bigbmp: { file: "art/generated/rasterbig.png" },
      backdropbmp: { file: "art/generated/backdrop.png" },
    },
    fonts: { ProbeBlocks: probeBlocksFont() },
    texts: {
      [P.text.id]: t(P.text, "ProbeBlocks"),
      [P.textMissing.id]: t(P.textMissing, "ProbeBlocks"),
      fontMissingText: t(P.text, "Peralta"),
    },
    sprites,
    exports: { ArtProbeRaster: "ArtProbeRaster", ArtProbeFontMissing: "ArtProbeFontMissing", ArtProbeBackdrop: "ArtProbeBackdrop" },
  };
}

const SLOTS = ["tail", "leg2", "arm2", "body", "leg1", "arm1", "head"];

/**
 * Experiment A0's probe scene plus the raster cat frame: the labels probeRasterF / probeRasterB on its one
 * _Append_CatTest donor (CatAppendRoot) placing CatRasterRig — CatProbe's empty slots at the same vanilla idleF
 * matrices, the marker at (-48, -330), a 16-level gray ramp as a bitmap and as vector gray:N squares. In the donor of
 * probe.swf, not in raster.swf: OBSERVED 2026-10-22 that a second mod SWF exporting _Append_CatTest left neither
 * file's appended labels playable (the A0 frame stopped showing too). Idempotent.
 */
export function withRasterCatFrame(probe: Scene): Scene {
  const P = RASTER_PROBE;
  const sc: Scene = JSON.parse(JSON.stringify(probe)) as Scene;
  const cp = sc.sprites.CatProbe;
  const donor = sc.sprites.CatAppendRoot;
  if (!cp || !donor) throw new Error("withRasterCatFrame: probe.scene.json has no CatProbe / CatAppendRoot");
  sc.bitmaps = { ...(sc.bitmaps || {}), gray16bmp: { file: "art/raster-gray16.png" } };
  sc.shapes.gray16 = { paths: [{ d: rect(16, 1), fill: "bitmap:gray16bmp", transform: [P.cat.bitmapRamp.w / 16, 0, 0, P.cat.bitmapRamp.h, 0, 0] }] };
  sc.shapes.vramp = { paths: Array.from({ length: 16 }, (_, n) => ({ d: `M${n * 16} 0 L${n * 16 + 16} 0 L${n * 16 + 16} ${P.cat.vectorRamp.h} L${n * 16} ${P.cat.vectorRamp.h} Z`, fill: `gray:${n}` })) };
  for (const slot of SLOTS) sc.sprites[`CatRaster_${slot}`] = { frames: 1, labels: {}, layers: [] };
  const slotKey = (slot: string): SceneKey => { const l = cp.layers.find((x) => x.name === slot); return { ...(l && l.keys[0] ? l.keys[0] : { frame: 0, x: 0, y: 0 }), frame: 0, ref: `CatRaster_${slot}` } as SceneKey; };
  sc.sprites.CatRasterRig = {
    frames: 24,
    labels: { idle: 0 },
    rig: "cat",
    parts: "game",
    layers: [
      ...SLOTS.map((slot, i) => ({ name: slot, depth: 1 + 2 * i, keys: [slotKey(slot)] })),
      { name: "marker", depth: 15, keys: [place("CatProbeMc_marker", P.cat.marker.x, P.cat.marker.y)] },
      { name: "bitmapRamp", depth: 16, keys: [place("gray16", P.cat.bitmapRamp.x, P.cat.bitmapRamp.y)] },
      { name: "vectorRamp", depth: 17, keys: [place("vramp", P.cat.vectorRamp.x, P.cat.vectorRamp.y)] },
    ],
  };
  const labels = donor.labels || {};
  const ani = donor.layers.find((l) => l.name === "ani")!;
  const at = labels.probeRasterF ?? donor.frames;
  labels.probeRasterF = at;
  labels.probeRasterB = at + 1;
  donor.labels = labels;
  ani.keys = ani.keys.filter((k) => k.frame !== at && k.frame !== at + 1);
  ani.keys.push({ frame: at, ref: "CatRasterRig", x: 3.85, y: -47.95 }, { frame: at + 1, ref: "CatRasterRig", x: 3.85, y: -47.95 });
  ani.keys.sort((x, y) => x.frame - y.frame);
  donor.frames = Math.max(donor.frames, at + 2);
  return sc;
}

/** Rename the font class of the `fontMissingText` box from Peralta to RASTER_PROBE.missingFontClass, in the SWF bytes. */
export function patchMissingFontClass(swf: Uint8Array): { bytes: Uint8Array; patched: number } {
  const from = new TextEncoder().encode("Peralta\u0000"), to = new TextEncoder().encode(`${RASTER_PROBE.missingFontClass}\u0000`);
  const out = new Uint8Array(swf);
  let patched = 0;
  outer: for (let i = 0; i + from.length <= out.length; i++) {
    for (let k = 0; k < from.length; k++) if (out[i + k] !== from[k]) continue outer;
    out.set(to, i);
    patched++;
  }
  return { bytes: out, patched };
}

// ---- measures -------------------------------------------------------------------------------------------------------
/** screen px of a clip point given as an offset from the marker's top-left */
export function clipToScreen(g: ShotGeometry, dx: number, dy: number): [number, number] {
  return [g.mirrored ? g.box.x1 + 1 - dx * g.scale : g.box.x0 + dx * g.scale, g.box.y0 + dy * g.scale];
}

function px(img: RgbaImageLike, x: number, y: number): Rgb | null {
  x = Math.round(x); y = Math.round(y);
  if (x < 0 || y < 0 || x >= img.width || y >= img.height) return null;
  const i = (y * img.width + x) * 4;
  return [img.rgba[i]!, img.rgba[i + 1]!, img.rgba[i + 2]!];
}

/** mean colour of the (2r+1)² patch around a clip point */
export function patchAt(img: RgbaImageLike, g: ShotGeometry, dx: number, dy: number, r = 2): Rgb {
  const [cx, cy] = clipToScreen(g, dx, dy);
  let n = 0, s0 = 0, s1 = 0, s2 = 0;
  for (let y = -r; y <= r; y++) for (let x = -r; x <= r; x++) { const p = px(img, cx + x, cy + y); if (p) { s0 += p[0]; s1 += p[1]; s2 += p[2]; n++; } }
  return n ? [Math.round(s0 / n), Math.round(s1 / n), Math.round(s2 / n)] : [0, 0, 0];
}

/** chromaticity distance (each colour scaled to unit sum): tint-independent */
export function chromaDistance(a: Rgb, b: Rgb): number {
  const na = a[0] + a[1] + a[2] || 1, nb = b[0] + b[1] + b[2] || 1;
  return Math.abs(a[0] / na - b[0] / nb) + Math.abs(a[1] / na - b[1] / nb) + Math.abs(a[2] / na - b[2] / nb);
}

/** true when the colour is (nearly) gray: its channels within 10 % of the brightest */
export function isGrayish(c: Rgb): boolean {
  const mx = Math.max(...c), mn = Math.min(...c);
  return mx < 8 || (mx - mn) / mx < 0.1;
}

/** samples of a clip-space rectangle on a grid (screen-px steps), offsets from the marker */
function samples(img: RgbaImageLike, g: ShotGeometry, x: number, y: number, w: number, h: number, inset = 0.15): Rgb[] {
  const out: Rgb[] = [];
  const step = 1 / g.scale;
  for (let cy = y + h * inset; cy <= y + h * (1 - inset); cy += step) for (let cx = x + w * inset; cx <= x + w * (1 - inset); cx += step) {
    const [sx, sy] = clipToScreen(g, cx, cy);
    const p = px(img, sx, sy);
    if (p) out.push(p);
  }
  return out;
}

const isRed = (c: Rgb) => c[0] > 1.6 * c[2] && c[0] > 1.6 * c[1] && c[0] > 60;
const isBlue = (c: Rgb) => c[2] > 1.6 * c[0] && c[2] > 1.6 * c[1] && c[2] > 60;
/** a red/blue blend (purple-ish): both red and blue present at comparable strength */
const isMixed = (c: Rgb) => c[0] > 40 && c[2] > 40 && c[0] < 2.2 * c[2] && c[2] < 2.2 * c[0] && c[1] < 0.6 * Math.max(c[0], c[2]);

export interface RasterShotMeasure {
  quad: { tl: Rgb; tr: Rgb; bl: Rgb; br: Rgb; ok: boolean };
  /** share of red/blue blended pixels across each stripe (sampled along its middle row) */
  stripes: { smoothMixed: number; snappedMixed: number; verdict: "smooth-vs-snapped" | "both-smooth" | "both-snapped" | "unreadable" };
  /** red↔blue changes along the tile's middle row: repeat ≈ 2·w/period − 1, clipped (streaked) ≈ 1 */
  tile: { transitions: number; amplitude: number; verdict: "repeats" | "clamped" | "unreadable" };
  /** the three flat blocks, and the luminance spread over the 1-texel checker block minified ×0.25 */
  big: { tl: Rgb; tr: Rgb; bl: Rgb; blocksOk: boolean; checkerMean: number; checkerStd: number; verdict: "mipmapped" | "aliased" | "unreadable" };
  font: TextInk;
  fontMissingGlyph: TextInk & { blobs: number[]; gapPx: number };
}

export interface TextInk {
  /** ink pixels (orange-ish) in the text box, screen px */
  ink: number;
  /** what solid ProbeBlocks glyphs would cover, screen px */
  expected: number;
  /** ink / the ink's bounding box */
  fillRatio: number;
  verdict: "embedded-font" | "other-font" | "nothing";
}

/** #ff6000 under the unit tint: red dominant, green about a third of it, little blue */
const isOrange = (c: Rgb) => c[0] > 90 && c[1] > 0.18 * c[0] && c[1] < 0.6 * c[0] && c[2] < 0.3 * c[0];

/** the orange ink of a text box: a per-column count list too (for blob splitting) */
function textInk(img: RgbaImageLike, g: ShotGeometry, box: { x: number; y: number; w: number; h: number }, expectedClipArea: number): TextInk & { columns: number[] } {
  const w = Math.round(box.w * g.scale), h = Math.round(box.h * g.scale);
  const columns = new Array(w).fill(0) as number[];
  let ink = 0, x0 = Infinity, x1 = -1, y0 = Infinity, y1 = -1;
  for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) {
    const [sx, sy] = clipToScreen(g, box.x - box.w / 2 + i / g.scale, box.y - box.h / 2 + j / g.scale);
    const p = px(img, sx, sy);
    if (p && isOrange(p)) { ink++; columns[i]!++; if (i < x0) x0 = i; if (i > x1) x1 = i; if (j < y0) y0 = j; if (j > y1) y1 = j; }
  }
  const bbox = ink ? (x1 - x0 + 1) * (y1 - y0 + 1) : 0;
  const expected = Math.round(expectedClipArea * g.scale * g.scale);
  const fillRatio = bbox ? ink / bbox : 0;
  const verdict = ink < 30 ? "nothing" : ink >= 0.5 * expected && fillRatio >= 0.55 ? "embedded-font" : "other-font";
  return { ink, expected, fillRatio: Math.round(fillRatio * 1000) / 1000, verdict, columns };
}

/** glyph area of a ProbeBlocks string at `size` px, clip px² */
export function blockTextArea(text: string, size: number): number {
  const s = size / FONT_EM;
  let a = 0;
  for (const ch of text) a += ch === "H" ? 700 * 700 : ch === "I" ? 100 * 700 : 0;
  return a * s * s;
}

export function measureRasterShot(img: RgbaImageLike, g: ShotGeometry): RasterShotMeasure {
  const P = RASTER_PROBE;
  // quad: the four quadrant centres
  const qs = P.quad.size;
  const quad = { tl: patchAt(img, g, P.quad.x + qs / 4, P.quad.y + qs / 4), tr: patchAt(img, g, P.quad.x + (3 * qs) / 4, P.quad.y + qs / 4), bl: patchAt(img, g, P.quad.x + qs / 4, P.quad.y + (3 * qs) / 4), br: patchAt(img, g, P.quad.x + (3 * qs) / 4, P.quad.y + (3 * qs) / 4) };
  const qc = P.quadColours;
  const quadOk = chromaDistance(quad.tl, qc.tl) < 0.25 && chromaDistance(quad.tr, qc.tr) < 0.25 && chromaDistance(quad.bl, qc.bl) < 0.25 && chromaDistance(quad.br, qc.br) < 0.25;
  // stripes: the middle row, from the first texel centre to the last (inside the bitmap: no edge clamp involved)
  const row = (s: { x: number; y: number; w: number; h: number }) => {
    const out: Rgb[] = [];
    for (let cx = s.x + s.w / 8; cx <= s.x + (7 * s.w) / 8; cx += 1 / g.scale) { const [sx, sy] = clipToScreen(g, cx, s.y + s.h / 2); const p = px(img, sx, sy); if (p) out.push(p); }
    return out;
  };
  const share = (cs: Rgb[]) => (cs.length ? cs.filter(isMixed).length / cs.length : 0);
  const sm = row(P.stripeSmooth), sn = row(P.stripeSnapped);
  const smoothMixed = share(sm), snappedMixed = share(sn);
  const anyColour = (cs: Rgb[]) => cs.some(isRed) && cs.some(isBlue);
  const stripes = {
    smoothMixed: Math.round(smoothMixed * 1000) / 1000,
    snappedMixed: Math.round(snappedMixed * 1000) / 1000,
    verdict: (!anyColour(sm) || !anyColour(sn) ? "unreadable" : smoothMixed > 0.15 && snappedMixed < 0.05 ? "smooth-vs-snapped" : smoothMixed > 0.15 ? "both-smooth" : "both-snapped") as RasterShotMeasure["stripes"]["verdict"],
  };
  // tile: the red − blue signal along a row through the first tile row; crossings of its mean (with hysteresis) count
  // the periods. OBSERVED 2026-10-22: a 2×2 tile at 8 clip px per texel comes out mostly blended (±10 around purple),
  // so the amplitude is recorded and the decision only needs the crossings
  const sig: number[] = [];
  for (let cx = P.tile.x + 1; cx <= P.tile.x + P.tile.w - 1; cx += 1 / g.scale) {
    const [sx, sy] = clipToScreen(g, cx, P.tile.y + P.tile.h / 4);
    const p = px(img, sx, sy);
    if (p) sig.push(p[0] - p[2]);
  }
  const mean = sig.length ? sig.reduce((x, v) => x + v, 0) / sig.length : 0;
  const amp = sig.length ? Math.max(...sig) - Math.min(...sig) : 0;
  const hy = Math.max(3, amp * 0.2);
  let transitions = 0, side = 0;
  for (const v of sig) { const sd = v > mean + hy ? 1 : v < mean - hy ? -1 : 0; if (sd && side && sd !== side) transitions++; if (sd) side = sd; }
  const tile = { transitions, amplitude: Math.round(amp), verdict: (sig.length < 10 || amp < 6 ? "unreadable" : transitions >= (2 * P.tile.w) / P.tile.period - 3 ? "repeats" : transitions <= 2 ? "clamped" : "unreadable") as RasterShotMeasure["tile"]["verdict"] };
  // big: block centres + the checker block's luminance spread
  const B = P.big, bc = P.bigColours;
  const big0 = { tl: patchAt(img, g, B.x + B.w / 4, B.y + B.h / 4), tr: patchAt(img, g, B.x + (3 * B.w) / 4, B.y + B.h / 4), bl: patchAt(img, g, B.x + B.w / 4, B.y + (3 * B.h) / 4) };
  const blocksOk = chromaDistance(big0.tl, bc.tl) < 0.25 && chromaDistance(big0.tr, bc.tr) < 0.25 && chromaDistance(big0.bl, bc.bl) < 0.25;
  const ck = samples(img, g, B.x + B.w / 2, B.y + B.h / 2, B.w / 2, B.h / 2, 0.2).map((c) => (c[0] + c[1] + c[2]) / 3);
  const cmean = ck.length ? ck.reduce((s, v) => s + v, 0) / ck.length : 0;
  const std = ck.length ? Math.sqrt(ck.reduce((s, v) => s + (v - cmean) * (v - cmean), 0) / ck.length) : 0;
  const big = { ...big0, blocksOk, checkerMean: Math.round(cmean), checkerStd: Math.round(std * 10) / 10, verdict: (!blocksOk || !ck.length ? "unreadable" : std < 0.2 * Math.max(cmean, 1) ? "mipmapped" : "aliased") as RasterShotMeasure["big"]["verdict"] };
  // fonts
  const ft = textInk(img, g, P.text, blockTextArea(P.text.text, P.text.size));
  const fm = textInk(img, g, P.textMissing, blockTextArea(P.textMissing.text, P.textMissing.size));
  // blobs along x in the missing-glyph box: runs of inked columns (a gap of >= 2 columns splits)
  const blobs: number[] = [];
  let run = 0, gap = 0, gapPx = 0, gapRun = 0;
  for (const c of fm.columns) {
    if (c > 2) { if (run === 0 && blobs.length) gapPx = Math.max(gapPx, gapRun); run++; gap = 0; gapRun = 0; }
    else { gap++; gapRun++; if (run && gap >= 2) { blobs.push(run); run = 0; } }
  }
  if (run) blobs.push(run);
  const strip = (t: TextInk & { columns: number[] }): TextInk => ({ ink: t.ink, expected: t.expected, fillRatio: t.fillRatio, verdict: t.verdict });
  return { quad: { ...quad, ok: quadOk }, stripes, tile, big, font: strip(ft), fontMissingGlyph: { ...strip(fm), blobs, gapPx: Math.round((gapPx / g.scale) * 10) / 10 } };
}

export interface CatRampMeasure {
  /** per gray level: measured bitmap cell, vector cell, the palette row's colour and the class of each */
  levels: Array<{ level: number; bitmap: Rgb; vector: Rgb; palette: Rgb; bitmapClass: "palette" | "gray" | "other"; vectorClass: "palette" | "gray" | "other" }>;
  /** over the levels whose palette colour is clearly not gray */
  bitmap: "remapped" | "gray" | "mixed" | "unreadable";
  vector: "remapped" | "gray" | "mixed" | "unreadable";
}

/** The cat frame's two gray ramps, offsets relative to the rig marker. `palRow`: the 16 colours of palette row 54. */
export function measureCatRamp(img: RgbaImageLike, g: ShotGeometry, palRow: Rgb[]): CatRampMeasure {
  const C = RASTER_PROBE.cat;
  const mx = C.marker.x, my = C.marker.y;
  const levels: CatRampMeasure["levels"] = [];
  const cls = (c: Rgb, pal: Rgb): "palette" | "gray" | "other" => (isGrayish(c) ? "gray" : chromaDistance(c, pal) < 0.12 ? "palette" : "other");
  for (let n = 0; n < 16; n++) {
    const pal = palRow[n] || [0, 0, 0];
    const bitmap = patchAt(img, g, C.bitmapRamp.x - mx + (n + 0.5) * (C.bitmapRamp.w / 16), C.bitmapRamp.y - my + C.bitmapRamp.h / 2, 1);
    const vector = patchAt(img, g, C.vectorRamp.x - mx + (n + 0.5) * (C.vectorRamp.w / 16), C.vectorRamp.y - my + C.vectorRamp.h / 2, 1);
    levels.push({ level: n, bitmap, vector, palette: pal, bitmapClass: cls(bitmap, pal), vectorClass: cls(vector, pal) });
  }
  const decide = (k: "bitmapClass" | "vectorClass") => {
    const telling = levels.filter((l) => !isGrayish(l.palette) && l.palette.some((v) => v > 40));
    if (!telling.length) return "unreadable" as const;
    const p = telling.filter((l) => l[k] === "palette").length, gr = telling.filter((l) => l[k] === "gray").length;
    return p >= 0.75 * telling.length ? ("remapped" as const) : gr >= 0.75 * telling.length ? ("gray" as const) : p + gr === 0 ? ("unreadable" as const) : ("mixed" as const);
  };
  return { levels, bitmap: decide("bitmapClass"), vector: decide("vectorClass") };
}

/** share of the shot's pixels whose chromaticity matches each backdrop half (purple / teal), tint-independent */
export function backdropShare(img: RgbaImageLike): { left: number; right: number } {
  const L = RASTER_PROBE.backdrop.left, R = RASTER_PROBE.backdrop.right;
  let l = 0, r = 0, n = 0;
  for (let y = 0; y < img.height; y += 4) for (let x = 0; x < img.width; x += 4) {
    const i = (y * img.width + x) * 4;
    const c: Rgb = [img.rgba[i]!, img.rgba[i + 1]!, img.rgba[i + 2]!];
    n++;
    if (Math.max(...c) < 25) continue;
    if (chromaDistance(c, L) < 0.08) l++;
    else if (chromaDistance(c, R) < 0.08) r++;
  }
  return { left: Math.round((l / n) * 10000) / 10000, right: Math.round((r / n) * 10000) / 10000 };
}
